with base as (select *, substring(supplier_name, 1, 2) as supplier_name_prefix from suppliers where rating > 2.9 and rating < 1.9), summary as (select case when rating >= 3.7 then 'high' when rating >= 1.5 then 'mid' else 'low' end as rating_bucket, sum(rating) as total_rating, count(case when city = 'Bangkok' then 1 end) as bangkok_count from base group by case when rating >= 3.7 then 'high' when rating >= 1.5 then 'mid' else 'low' end) select rating_bucket, total_rating, bangkok_count from summary where total_rating < 12 order by total_rating
